var PM = window.__PM || (window.__PM = {});

PM.scene = function(id, whip){
  MSD.cls('.pm-sc', 'on', false);
  MSD.cls('#pm-sc-' + id, 'on', true);
  MSD.cls('#pm-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#pm-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

PM.header = function(app, count, tone, health){
  MSD.q('#pm-app').textContent = app;
  MSD.q('#pm-rt-n').textContent = count;
  MSD.cls('#pm-rt', 'bad', tone === 'bad');
  MSD.cls('#pm-rt', 'ok', tone === 'ok');
  MSD.cls('#pm-health', 'bad', tone === 'bad');
  MSD.cls('#pm-health', 'warn', tone === 'warn');
  MSD.q('#pm-health-t').textContent = health;
};

/** state: '' | 'hot' | 'bad'; badge tone: '' | 'ok' | 'warn' | 'bad' */
PM.tile = function(id, state, badge, badgeTone, sub){
  MSD.cls('#pm-t-' + id, 'hot', state === 'hot');
  MSD.cls('#pm-t-' + id, 'bad', state === 'bad');
  if(badge != null) MSD.q('#pm-b-' + id).textContent = badge;
  if(badgeTone != null){
    var b = MSD.q('#pm-b-' + id);
    b.className = 'pm-t-b' + (badgeTone ? ' ' + badgeTone : '');
  }
  if(sub != null) MSD.q('#pm-s-' + id).textContent = sub;
};

PM.hop = function(n, on, tone){
  MSD.q('#pm-h-' + n).className = 'pm-hop' + (on ? ' on' : '') + (tone ? ' ' + tone : '');
};

PM.banner = function(icon, text, right, bad){
  MSD.cls('#pm-banner', 'bad', !!bad);
  MSD.q('#pm-b-ic').textContent = icon;
  MSD.q('#pm-b-t').textContent = text;
  MSD.q('#pm-b-n').textContent = right;
};

PM.strip = function(id, label, text, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'warn', tone === 'warn');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-l').textContent = label;
  MSD.q(id + '-t').textContent = text;
};

/** Lights the delivery-count pips; the tenth turns red. */
PM.pips = function(n){
  MSD.qa('#pm-pips i').forEach(function(el, i){
    el.classList.toggle('on', i < n && i < 9);
    el.classList.toggle('dead', n >= 10 && i === 9);
  });
  MSD.q('#pm-k-n').textContent = n + ' / 10';
};

PM.count = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = Math.round(from + (to - from) * p).toLocaleString('en-US');
    if(p >= 1) clearInterval(id);
  });
};

PM.scene('flow');
PM.header('orders · service bus · 40/min', '0', '', 'all green');
PM.banner('✅', 'inventory-api · 200 OK · every call', '—', false);
PM.tile('orders', '', 'steady', 'ok', '40 a minute');
PM.tile('queue', '', '0 deep', 'ok', 'peek-lock · 30s');
PM.tile('worker', '', 'healthy', 'ok', 'functions trigger');
PM.tile('api', '', '200 OK', 'ok', 'reserve stock');
PM.hop(1, true); PM.hop(2, true); PM.hop(3, true);
MSD.cls('#pm-dlq', 'on', false);
MSD.q('#pm-d-n').textContent = '0';
MSD.q('#pm-d-s').textContent = 'empty';
PM.strip('#pm-strip', 'NORMAL', 'Nothing here is misconfigured. Every default is the default Azure gives you.', '');

MSD.after(700, function(){
  MSD.q('#pm-s-queue').textContent = 'MaxDeliveryCount 10';
  MSD.punch('#pm-t-queue', 2);
  MSD.sfx.blip(2);
});
MSD.after(1900, function(){
  PM.strip('#pm-strip', 'DEFAULTS', 'MaxDeliveryCount 10. LockDuration 30 seconds. Nobody changed either one.', '');
  MSD.punch('#pm-strip', 3);
});

var PM = window.__PM;

PM.scene('flow');
PM.header('orders · inventory-api down', '0', 'warn', 'degraded');
PM.banner('🔥', 'inventory-api · 503 · 180ms · every call', '00:00', true);
PM.tile('orders', '', 'steady', 'ok', '40 a minute');
PM.tile('queue', '', 'filling', 'warn', 'MaxDeliveryCount 10');
PM.tile('worker', 'hot', 'retrying', 'warn', 'unhandled exception');
PM.tile('api', 'bad', '503', 'bad', 'reserve stock');
PM.hop(1, true); PM.hop(2, true); PM.hop(3, true, 'bad');
MSD.cls('#pm-dlq', 'on', false);
PM.strip('#pm-strip', 'FAST FAILURE', 'It answers in 180 milliseconds. That speed is about to be the problem.', 'warn');

MSD.after(500, function(){ MSD.shake('#pm-t-api'); MSD.sfx.error(); });
MSD.after(1500, function(){
  MSD.q('#pm-b-n').textContent = '00:12';
  MSD.punch('#pm-banner', 3);
});
MSD.after(2400, function(){
  PM.strip('#pm-strip', 'THE HANDLER', 'The function throws, the trigger abandons the message, and the broker hands it straight back.', 'warn');
  MSD.sfx.blip(3);
});

var PM = window.__PM;

PM.scene('shred', true);
PM.header('order 41883 · one message', '0', 'warn', 'retrying');
MSD.q('#pm-c-a-n').textContent = '0.0s';
MSD.q('#pm-c-a-s').textContent = 'attempt 1 of 10';
MSD.q('#pm-c-b-n').textContent = '18:00';
MSD.q('#pm-c-b-s').textContent = 'inventory-api is still returning 503';
PM.pips(0);
MSD.cls('.pm-l-row', 'on', false);
PM.strip('#pm-strip-2', 'WATCH', 'Two clocks. One is the message. The other is the outage it is dying inside.', '');

// The pip ladder is the beat — ten deliveries, no gap between them.
for (var k = 1; k <= 10; k++){
  (function(k){
    MSD.after(300 + k * 190, function(){
      PM.pips(k);
      MSD.q('#pm-c-a-n').textContent = (k * 0.41).toFixed(1) + 's';
      MSD.q('#pm-c-a-s').textContent = 'attempt ' + k + ' of 10';
      if(k < 10) MSD.sfx.tick();
    });
  })(k);
}
MSD.after(700, function(){ MSD.cls('#pm-l-1', 'on', true); });
MSD.after(1100, function(){ MSD.cls('#pm-l-2', 'on', true); });
MSD.after(1900, function(){ MSD.cls('#pm-l-3', 'on', true); });
MSD.after(2400, function(){
  MSD.cls('#pm-l-4', 'on', true);
  MSD.q('#pm-c-a-s').textContent = 'dead-lettered';
  MSD.punch('#pm-clock-a', 4);
  MSD.sfx.thud();
});
MSD.after(3300, function(){
  PM.strip('#pm-strip-2', 'GONE', 'Four point one seconds from first delivery to the dead-letter queue.', 'bad');
});

var PM = window.__PM;

PM.scene('shred');
PM.header('order 41883 · one message', '1', 'bad', 'dead-lettered');
MSD.q('#pm-c-a-n').textContent = '4.1s';
MSD.q('#pm-c-a-s').textContent = 'dead-lettered';
MSD.q('#pm-c-b-n').textContent = '17:56';
PM.pips(10);
MSD.cls('.pm-l-row', 'on', true);
PM.strip('#pm-strip-2', 'NO WAIT', 'An abandoned message is redelivered at once. Nothing sits between the attempts.', 'bad');

MSD.after(700, function(){
  MSD.q('#pm-c-a-s').textContent = 'ten attempts, zero delay';
  MSD.punch('#pm-count', 2);
  MSD.sfx.blip(2);
});
MSD.after(1800, function(){
  PM.strip('#pm-strip-2', 'THE SETTING', 'MaxDeliveryCount sets how many attempts. There is no setting for the gap.', 'bad');
  MSD.punch('#pm-strip-2', 4);
  MSD.sfx.error();
});
MSD.after(3000, function(){
  MSD.q('#pm-c-b-s').textContent = 'and it has barely started';
  MSD.punch('#pm-clock-b', 3);
});

var PM = window.__PM;

PM.scene('shred');
PM.header('order 41883 · one message', '1', 'bad', 'dead-lettered');
MSD.q('#pm-c-a-n').textContent = '4.1s';
MSD.q('#pm-c-a-s').textContent = 'ten attempts, zero delay';
MSD.q('#pm-c-b-n').textContent = '18:00';
MSD.q('#pm-c-b-s').textContent = 'and it had barely started';
PM.pips(10);
MSD.cls('.pm-l-row', 'on', true);
PM.strip('#pm-strip-2', 'MISMATCH', 'A retry window of four seconds against a failure measured in minutes.', 'bad');

MSD.after(600, function(){
  MSD.punch('#pm-clock-a', 1);
  MSD.sfx.blip(1);
});
MSD.after(1100, function(){
  MSD.punch('#pm-clock-b', 3);
  MSD.sfx.blip(3);
});
MSD.after(2000, function(){
  PM.strip('#pm-strip-2', 'AND AGAIN', 'The next order arrives, and the same four seconds happen to it.', 'bad');
  MSD.sfx.error();
});

var PM = window.__PM;

PM.scene('flow', true);
PM.header('orders · draining into the DLQ', '0', 'bad', 'shredding');
PM.banner('🔥', 'inventory-api · 503 · 180ms · every call', '18:00', true);
PM.tile('orders', '', 'steady', 'ok', '40 a minute');
PM.tile('queue', '', '0 deep', 'bad', 'never backs up');
PM.tile('worker', 'hot', 'shredding', 'bad', 'abandon ×10, then DLQ');
PM.tile('api', 'bad', '503', 'bad', 'still down');
PM.hop(1, true); PM.hop(2, true); PM.hop(3, true, 'bad');
MSD.cls('#pm-dlq', 'on', true);
MSD.q('#pm-d-s').textContent = 'filling at 40 a minute';
PM.strip('#pm-strip', 'THE TELL', 'Queue depth stayed at zero the whole time. Every dashboard looked healthy.', 'bad');

MSD.after(400, function(){
  PM.count('#pm-d-n', 0, 720, 2200);
  PM.count('#pm-rt-n', 0, 720, 2200);
  MSD.sfx.riser(2000);
});
MSD.after(2800, function(){
  MSD.punch('#pm-dlq', 4);
  MSD.sfx.thud();
  MSD.q('#pm-d-s').textContent = '720 orders · reason: MaxDeliveryCountExceeded';
});

var PM = window.__PM;

PM.scene('flow');
PM.header('orders · after the outage', '720', 'bad', 'recovered');
PM.banner('✅', 'inventory-api · 200 OK · recovered at 11:21', '18:00', false);
PM.tile('orders', '', 'steady', 'ok', '40 a minute');
PM.tile('queue', '', '0 deep', 'ok', 'MaxDeliveryCount 10');
PM.tile('worker', '', 'healthy', 'ok', 'functions trigger');
PM.tile('api', '', '200 OK', 'ok', 'reserve stock');
PM.hop(1, true); PM.hop(2, true); PM.hop(3, true);
MSD.cls('#pm-dlq', 'on', true);
MSD.q('#pm-d-n').textContent = '720';
MSD.q('#pm-d-s').textContent = '720 orders · reason: MaxDeliveryCountExceeded';
PM.strip('#pm-strip', 'AWKWARD', 'The dependency is fine now. The orders it killed are still sitting there.', 'bad');

MSD.after(900, function(){
  MSD.q('#pm-d-s').textContent = 'every one of them would work right now';
  MSD.punch('#pm-dlq', 3);
  MSD.sfx.blip(3);
});
MSD.after(2100, function(){
  PM.strip('#pm-strip', 'THE NAME', 'We call it a poison-message guard. Not one of these messages was poison.', 'bad');
  MSD.punch('#pm-strip', 4);
  MSD.sfx.error();
});

var PM = window.__PM;

PM.scene('shred', true);
PM.header('the misread setting', '720', 'bad', 'by design');
MSD.q('#pm-c-a-n').textContent = '10';
MSD.q('#pm-c-a-s').textContent = 'attempts — you set this';
MSD.q('#pm-c-b-n').textContent = '0s';
MSD.q('#pm-c-b-s').textContent = 'gap between them — you cannot set this';
PM.pips(10);
MSD.cls('.pm-l-row', 'on', false);
PM.strip('#pm-strip-2', 'READ IT AGAIN', 'Every retry knob Service Bus gives you is a count. None of them is a duration.', 'bad');

MSD.after(700, function(){ MSD.punch('#pm-clock-a', 1); MSD.sfx.blip(1); });
MSD.after(1400, function(){ MSD.punch('#pm-clock-b', 3); MSD.sfx.error(); });
MSD.after(2400, function(){
  PM.strip('#pm-strip-2', 'ITS REAL JOB', 'It is a blast-radius cap for a genuinely bad message — and it is good at that.', '');
  MSD.sfx.blip(4);
});
MSD.after(3400, function(){
  MSD.q('#pm-c-b-s').textContent = 'there is no property for it';
  MSD.punch('#pm-strip-2', 5);
});

var PM = window.__PM;

PM.scene('ladder', true);
PM.header('the fix · scheduled retry', '720', '', 'rebuilding');
PM.strip('#pm-strip-3', 'HOW', 'Complete the message, re-enqueue a copy with ScheduledEnqueueTimeUtc, carry the attempt in a property.', '');

MSD.after(600, function(){ MSD.punch('#pm-lane-a', 1); MSD.sfx.error(); });
MSD.after(1600, function(){ MSD.punch('#pm-lane-b', 3); MSD.sfx.chime(); });
MSD.after(2700, function(){
  PM.strip('#pm-strip-3', 'WHY A COPY', 'A scheduled message is a new message, so DeliveryCount restarts. Count the attempts yourself.', '');
  MSD.sfx.blip(4);
});
MSD.after(3600, function(){
  PM.strip('#pm-strip-3', 'RESULT', 'Five attempts across forty minutes. The fifth one lands after the API is back.', 'good');
  MSD.punch('#pm-strip-3', 5);
});

var PM = window.__PM;

PM.scene('shred', true);
PM.header('the fix that is not one', '720', 'bad', 'still dead');
MSD.q('#pm-c-a-n').textContent = '41s';
MSD.q('#pm-c-a-s').textContent = 'MaxDeliveryCount raised to 100';
MSD.q('#pm-c-b-n').textContent = '17:19';
MSD.q('#pm-c-b-s').textContent = 'outage still to run';
PM.pips(10);
MSD.q('#pm-k-n').textContent = '100 / 100';
MSD.cls('.pm-l-row', 'on', false);
PM.strip('#pm-strip-2', 'TEMPTING', 'The first instinct is to turn the number up. Ten times the attempts, still zero delay.', 'warn');

MSD.after(800, function(){
  MSD.punch('#pm-clock-a', 2);
  MSD.sfx.error();
});
MSD.after(1800, function(){
  PM.strip('#pm-strip-2', 'ALSO NOT IT', 'ServiceBusRetryOptions will not save you either — that governs the client’s own calls, not redelivery.', 'bad');
  MSD.punch('#pm-strip-2', 4);
  MSD.sfx.thud();
});
MSD.after(3000, function(){
  MSD.q('#pm-c-a-s').textContent = '37 more seconds of an 18-minute outage';
});

var PM = window.__PM;

PM.scene('sort', true);
PM.header('sorting the two failures', '720', '', 'by hand');

MSD.hide('.pm-r');
MSD.after(350, function(){ MSD.show('#pm-sc-sort .pm-box.warn .pm-r', 180); });
MSD.after(1100, function(){ MSD.show('#pm-sc-sort .pm-box.bad .pm-r', 180); });
MSD.after(2100, function(){
  MSD.punch('#pm-sort-x', 4);
  MSD.sfx.lock();
});
MSD.after(3200, function(){ MSD.sfx.sparkle(); });

var PM = window.__PM;

PM.scene('final');
PM.header('orders · scheduled retry', '0', 'ok', 'survives');

MSD.hide('.pm-fin-p');
MSD.cls('#pm-save', 'ping', false);

MSD.after(200, function(){ MSD.punch('#pm-badge', 1); MSD.sfx.chime(); });
MSD.after(700, function(){ MSD.show('.pm-fin-p', 220); });
MSD.after(1900, function(){ MSD.cls('#pm-save', 'ping', true); MSD.sfx.sparkle(); });
MSD.after(2600, function(){ MSD.cls('#pm-save', 'ping', false); MSD.punch('#pm-badge', 4); });

