#stage .pm-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .pm-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .pm-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .pm-mark svg{ width:26px; height:26px; }
#stage .pm-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .pm-rt{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .pm-rt b{
  color:#fff; font-family:var(--font-mono); font-size:30px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .pm-rt.bad b{ color:var(--danger); }
#stage .pm-rt.ok b{ color:var(--success); }
#stage .pm-rt i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .pm-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pm-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .pm-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .pm-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .pm-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.7s; }
#stage .pm-health.warn b{ color:var(--warn); }
#stage .pm-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .pm-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .pm-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .pm-body{ position:relative; flex:1; min-height:0; }
#stage .pm-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .pm-sc.on{ opacity:1; transform:none; }
#stage .pm-sc.whip{ animation:pm-whip .44s cubic-bezier(.19,1,.22,1); }

/* shared strip -------------------------------------------------------- */
#stage .pm-strip{
  height:92px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pm-strip b{
  padding:7px 16px; border-radius:9px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:2px;
}
#stage .pm-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .pm-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.09); }
#stage .pm-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .pm-strip.warn{ border-color:rgba(240,166,74,.5); background:rgba(240,166,74,.09); }
#stage .pm-strip.warn b{ background:rgba(240,166,74,.2); color:var(--warn); }
#stage .pm-strip.good{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.09); }
#stage .pm-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ============================= SCENE 1 · FLOW ========================== */
#stage .pm-flow{ height:100%; display:flex; flex-direction:column; justify-content:center; gap:20px; }

#stage .pm-banner{
  height:88px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(63,185,80,.08); border:1.5px solid rgba(63,185,80,.45);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pm-banner.bad{
  background:rgba(244,74,106,.1); border-color:rgba(244,74,106,.6);
  animation:pm-alert 1.1s ease-in-out infinite;
}
#stage .pm-b-ic{ font-size:32px; line-height:1; flex-shrink:0; }
#stage .pm-b-t{ color:var(--text-primary); font-family:var(--font-mono); font-size:22px; font-weight:600; }
#stage .pm-b-n{
  margin-left:auto; flex-shrink:0; color:var(--text-dim);
  font-family:var(--font-mono); font-size:30px; font-weight:800; font-variant-numeric:tabular-nums;
}
#stage .pm-banner.bad .pm-b-n{ color:var(--danger); }

#stage .pm-pipe{ height:268px; flex-shrink:0; display:flex; align-items:stretch; }
#stage .pm-tile{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
  gap:12px; padding:18px 12px; border-radius:24px; text-align:center;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease;
}
#stage .pm-tile.hot{ border-color:rgba(58,160,255,.7); box-shadow:0 0 0 1px rgba(58,160,255,.28), 0 0 50px rgba(58,160,255,.2); }
#stage .pm-tile.bad{ border-color:rgba(244,74,106,.7); box-shadow:0 0 0 1px rgba(244,74,106,.28), 0 0 50px rgba(244,74,106,.2); }
#stage .pm-t-ic{
  width:66px; height:66px; border-radius:19px; flex-shrink:0; font-size:34px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .pm-tile b{ color:#fff; font-size:23px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .pm-tile i{
  color:var(--text-dim); font-family:var(--font-mono); font-size:17px; font-weight:600;
  font-style:normal; line-height:1.3;
}
#stage .pm-t-b{
  padding:7px 14px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.8); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .pm-t-b.ok{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.14); color:var(--success); }
#stage .pm-t-b.warn{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.14); color:var(--warn); }
#stage .pm-t-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

#stage .pm-hop{ position:relative; width:56px; flex-shrink:0; }
#stage .pm-hop::before{
  content:""; position:absolute; left:0; right:0; top:50%; margin-top:-1.5px;
  height:3px; border-radius:2px; background:var(--border); transition:background .3s ease;
}
#stage .pm-hop i{
  position:absolute; top:50%; margin-top:-6px; left:0;
  width:12px; height:12px; border-radius:50%; opacity:0;
  background:var(--accent-1); box-shadow:0 0 14px var(--accent-1);
}
#stage .pm-hop.on i{ animation:pm-hop 1s linear infinite; }
#stage .pm-hop.bad::before{ background:rgba(244,74,106,.55); }
#stage .pm-hop.bad i{ background:var(--danger); box-shadow:0 0 14px var(--danger); }
#stage .pm-hop i:nth-child(2){ animation-delay:.33s; }
#stage .pm-hop i:nth-child(3){ animation-delay:.66s; }

#stage .pm-dlq{
  height:120px; flex-shrink:0; display:flex; align-items:center; gap:18px;
  padding:0 24px; border-radius:24px;
  background:rgba(20,27,43,.6); border:1.5px dashed var(--border);
  opacity:.4; filter:saturate(.3);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease;
}
#stage .pm-dlq.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.6);
  background:rgba(244,74,106,.08);
  box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 50px rgba(244,74,106,.14);
}
#stage .pm-d-ic{
  width:60px; height:60px; border-radius:17px; flex-shrink:0; font-size:30px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.12); border:1.5px solid rgba(244,74,106,.3);
}
#stage .pm-d-t{ display:flex; flex-direction:column; gap:7px; min-width:0; }
#stage .pm-d-t b{ color:#fff; font-family:var(--font-mono); font-size:23px; font-weight:700; white-space:nowrap; }
#stage .pm-d-t i{ color:var(--text-dim); font-size:20px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .pm-d-n{
  margin-left:auto; flex-shrink:0; color:var(--danger);
  font-family:var(--font-mono); font-size:52px; font-weight:800;
  line-height:1; font-variant-numeric:tabular-nums;
}

/* ============================ SCENE 2 · SHRED ========================== */
#stage .pm-shred{ height:100%; display:flex; flex-direction:column; justify-content:center; gap:18px; }

#stage .pm-clocks{ height:224px; flex-shrink:0; display:flex; gap:18px; }
#stage .pm-clock{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
  gap:10px; padding:20px 16px; border-radius:28px; text-align:center;
}
#stage .pm-clock.bad{
  background:radial-gradient(circle at 50% 0%, rgba(244,74,106,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(244,74,106,.55);
  box-shadow:0 0 0 1px rgba(244,74,106,.18), 0 0 60px rgba(244,74,106,.14);
}
#stage .pm-clock.warn{
  background:radial-gradient(circle at 50% 0%, rgba(240,166,74,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(240,166,74,.5);
}
#stage .pm-c-l{ font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2.6px; }
#stage .pm-clock.bad .pm-c-l{ color:var(--danger); }
#stage .pm-clock.warn .pm-c-l{ color:var(--warn); }
#stage .pm-c-n{
  color:#fff; font-family:var(--font-mono); font-size:86px; font-weight:800;
  line-height:1; letter-spacing:-3px; font-variant-numeric:tabular-nums;
}
#stage .pm-c-s{ color:var(--text-dim); font-size:19px; font-weight:600; line-height:1.3; }

#stage .pm-count{
  height:88px; flex-shrink:0; display:flex; align-items:center; gap:18px;
  padding:0 24px; border-radius:22px;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
#stage .pm-k-l{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:700; flex-shrink:0; }
#stage .pm-pips{ flex:1; min-width:0; display:flex; align-items:center; gap:9px; }
#stage .pm-pips i{
  flex:1; height:20px; border-radius:6px; background:rgba(35,44,64,.9);
  transition:background .25s ease, box-shadow .25s ease;
}
#stage .pm-pips i.on{ background:linear-gradient(90deg,#F0A64A,#F4C46A); }
#stage .pm-pips i.dead{ background:linear-gradient(90deg,#F44A6A,#FF8FA3); box-shadow:0 0 16px rgba(244,74,106,.5); }
#stage .pm-k-n{
  flex-shrink:0; color:#fff; font-family:var(--font-mono); font-size:24px;
  font-weight:800; font-variant-numeric:tabular-nums;
}

#stage .pm-log{ flex-shrink:0; display:flex; flex-direction:column; gap:8px; }
#stage .pm-l-row{
  height:54px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 20px; border-radius:14px; white-space:nowrap;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease, opacity .3s ease;
  opacity:.35;
}
#stage .pm-l-row.on{ opacity:1; }
#stage .pm-l-row .t{
  width:78px; flex-shrink:0; color:var(--text-dim);
  font-family:var(--font-mono); font-size:19px; font-weight:700;
}
#stage .pm-l-row .m{
  color:var(--text-primary); font-family:var(--font-mono); font-size:19px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .pm-l-row .v{
  margin-left:auto; flex-shrink:0; padding:6px 14px; border-radius:100px;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .pm-l-row.dead{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.1); }
#stage .pm-l-row.dead .v{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

/* =========================== SCENE 3 · LADDER ========================== */
#stage .pm-ladder{ height:100%; display:flex; flex-direction:column; justify-content:center; gap:18px; }
#stage .pm-tl-h{
  display:flex; justify-content:space-between; flex-shrink:0;
  color:var(--text-dim); font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .pm-lane{ flex-shrink:0; display:flex; flex-direction:column; gap:12px; }
#stage .pm-lane-l{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; }
/* overflow stays visible so a marker at t≈0 is not sliced in half by the
   track's left edge; the band rounds its own corners instead. */
#stage .pm-tl{
  position:relative; height:66px; border-radius:16px;
  background:rgba(14,20,32,.8); border:1.5px solid var(--border);
}
#stage .pm-band{
  position:absolute; left:0; top:0; bottom:0; width:40%;
  border-radius:15px 0 0 15px;
  background:repeating-linear-gradient(135deg, rgba(244,74,106,.2) 0 12px, rgba(244,74,106,.09) 12px 24px);
  border-right:2px solid rgba(244,74,106,.55);
}
#stage .pm-mk{
  position:absolute; top:50%; margin-top:-13px; width:10px; height:26px;
  margin-left:-5px; border-radius:4px;
  background:var(--accent-1); box-shadow:0 0 14px rgba(58,160,255,.6);
}
#stage .pm-mk.bad{ background:var(--danger); box-shadow:0 0 14px rgba(244,74,106,.7); }
#stage .pm-mk.ok{ background:var(--success); box-shadow:0 0 18px rgba(63,185,80,.75); width:14px; }
#stage .pm-mk.a1{ left:0.2%; }
#stage .pm-mk.b1{ left:0.2%; }
#stage .pm-mk.b2{ left:1.3%; }
#stage .pm-mk.b3{ left:5.7%; }
#stage .pm-mk.b4{ left:23.5%; }
#stage .pm-mk.b5{ left:90.2%; }
#stage .pm-cluster, #stage .pm-hit{
  position:absolute; top:50%; transform:translateY(-50%);
  padding:6px 14px; border-radius:9px; white-space:nowrap;
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:1.2px;
}
#stage .pm-cluster{
  left:26px; border:1.5px solid rgba(244,74,106,.6);
  background:rgba(244,74,106,.16); color:var(--danger);
}
/* Sits to the LEFT of the 40-minute marker — at right:16px it covered it. */
#stage .pm-hit{
  right:12.5%; border:1.5px solid rgba(63,185,80,.6);
  background:rgba(63,185,80,.16); color:var(--success);
}
#stage .pm-lane-x{
  padding:11px 18px; border-radius:13px; align-self:flex-start;
  font-family:var(--font-mono); font-size:19px; font-weight:700;
}
#stage .pm-lane-x.bad{ background:rgba(244,74,106,.12); border:1.5px solid rgba(244,74,106,.5); color:var(--danger); }
#stage .pm-lane-x.ok{ background:rgba(63,185,80,.12); border:1.5px solid rgba(63,185,80,.5); color:var(--success); }
#stage .pm-band-k{
  flex-shrink:0; display:flex; align-items:center; gap:12px;
  color:var(--text-dim); font-size:19px; font-weight:600;
}
#stage .pm-band-k i{
  width:34px; height:16px; border-radius:5px; flex-shrink:0;
  background:repeating-linear-gradient(135deg, rgba(244,74,106,.35) 0 8px, rgba(244,74,106,.14) 8px 16px);
  border:1px solid rgba(244,74,106,.5);
}

/* ============================ SCENE 4 · SORT =========================== */
#stage .pm-sort{ height:100%; display:flex; flex-wrap:wrap; align-content:center; gap:18px; }
#stage .pm-box{
  flex:1 1 0; min-width:0; display:flex; flex-direction:column; align-items:center; gap:16px;
  padding:28px 20px; border-radius:28px; text-align:center;
}
#stage .pm-box.warn{
  background:radial-gradient(circle at 50% 0%, rgba(240,166,74,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(240,166,74,.5);
}
#stage .pm-box.bad{
  background:radial-gradient(circle at 50% 0%, rgba(244,74,106,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(244,74,106,.5);
}
#stage .pm-box-h{ font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:3px; }
#stage .pm-box.warn .pm-box-h{ color:var(--warn); }
#stage .pm-box.bad .pm-box-h{ color:var(--danger); }
#stage .pm-box-ic{ font-size:56px; line-height:1; color:var(--text-primary); }
#stage .pm-box-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .pm-r{
  padding:13px 10px; border-radius:13px;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border); color:var(--text-primary);
  font-family:var(--font-mono); font-size:19px; font-weight:600; line-height:1.25;
}
#stage .pm-box-x{
  width:100%; padding:14px 10px; border-radius:14px;
  font-family:var(--font-mono); font-size:19px; font-weight:800; line-height:1.3;
}
#stage .pm-box-x.warn{ background:rgba(240,166,74,.16); border:1.5px solid rgba(240,166,74,.6); color:var(--warn); }
#stage .pm-box-x.bad{ background:rgba(244,74,106,.16); border:1.5px solid rgba(244,74,106,.6); color:var(--danger); }
#stage .pm-sort-x{
  flex:1 1 100%; padding:22px 26px; border-radius:20px; text-align:center;
  background:linear-gradient(90deg, rgba(58,160,255,.16), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.5); color:var(--text-primary);
  font-size:25px; font-weight:600; line-height:1.35;
}
#stage .pm-sort-x b{ color:#fff; font-weight:800; }

/* =========================== SCENE 5 · PAYOFF ========================== */
#stage .pm-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:20px;
  text-align:center;
}
#stage .pm-badge{
  width:136px; height:136px; border-radius:38px; font-size:66px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.3), rgba(34,211,238,.14));
  border:2px solid rgba(58,160,255,.65);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 84px rgba(58,160,255,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .pm-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:4.5px; }
#stage .pm-fin-h{ color:#fff; font-size:62px; font-weight:900; line-height:1.14; letter-spacing:-2px; }
#stage .pm-fin-h em{ font-style:normal; color:var(--accent-1); }
#stage .pm-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .pm-fin-p{
  padding:13px 24px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:23px; font-weight:700;
}
#stage .pm-save{
  margin-top:6px; padding:18px 26px; border-radius:20px; max-width:880px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .pm-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes pm-hop{
  0%{ left:-6px; opacity:0; }
  22%{ opacity:1; }
  78%{ opacity:1; }
  100%{ left:52px; opacity:0; }
}
@keyframes pm-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes pm-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}
